insert into public.goal_events (season_id, team_id, event_type, player_id, goalkeeper_club_id, occurred_on, notes)
select s.id, t.id, 'gk_conceded'::public.goal_event_type, null, g.id,
  coalesce(v.acquired_date, '2023-08-01')::date,
  'import: expanded from spreadsheet cumulative AGAINST (GK ownership stint)'
from public.seasons s join public.teams t on t.season_id=s.id and s.name='2023/2024'
