insert into public.cup_ties (season_id, competition, round_name, home_team_id, away_team_id, home_name, away_name, home_score, away_score, played_on)
select s.id, v.competition, v.round_name, ht.id, at.id, v.home_name, v.away_name, v.home_score, v.away_score, v.played_on::date
from public.seasons s join (values
  ('dream_league_cup', '1st Round Qualifier', 'DREAMVILLE', 'ONE AND A HALF A HARPER FC', 'DREAMVILLE', 'ONE AND A HALF A HARPER FC', -1, -2, null),
  ('dream_league_cup', '1st Round Qualifier', 'SHEFSPANYOL', 'DUGGAN''S DREAMERS', 'SHEFSPANYOL', 'DUGGAN''S DREAMERS', 5, 0, null),
  ('dream_league_cup', '1st Round Qualifier', 'NUTMEG UTD', 'ERIMUS', 'NUTMEG UTD', 'ERIMUS', 1, 2, null),
  ('dream_league_cup', '1st Round Qualifier', 'MICHU IN DE GEA BAR', 'TIKI TAKA FC', 'MICHU IN DE GEA BAR', 'TIKI TAKA FC', 2, 2, null),
  ('dream_league_cup', '1st Round Qualifier', 'RASH IN THE ATTIC', 'DURHAM DYNAMO', 'RASH IN THE ATTIC', 'DURHAM DYNAMO', 3, 0, null),
  ('dream_league_cup', '1st Round Qualifier', 'CHARLIE''S ANGELS', 'SPORTING HOOF', 'CHARLIE''S ANGELS', 'SPORTING HOOF', -1, 1, null),
  ('dream_league_cup', 'Replays', 'MICHU IN DE GEA BAR', 'TIKI TAKA FC', 'MICHU IN DE GEA BAR', 'TIKI TAKA FC', 3, 0, null),
  ('dream_league_cup', 'Quarter Finals', 'CASEMIGOS', 'ERIMUS', 'CASEMIGOS', 'ERIMUS', 0, 0, null),
  ('dream_league_cup', 'Quarter Finals', 'SHEFSPANYOL', 'RASH IN THE ATTIC', 'SHEFSPANYOL', 'RASH IN THE ATTIC', 5, 1, null),
  ('dream_league_cup', 'Quarter Finals', 'DREAMVILLE', 'SPORTING HOOF', 'DREAMVILLE', 'SPORTING HOOF', 0, 2, null),
  ('dream_league_cup', 'Quarter Finals', 'MICHU IN DE GEA BAR', 'ROBS ROVERS', 'MICHU IN DE GEA BAR', 'ROBS ROVERS', 2, 2, null),
  ('dream_league_cup', 'Semi-Finals', 'ERIMUS', 'MICHU IN DE GEA BAR', 'ERIMUS', 'MICHU IN DE GEA BAR', 0, -1, null),
  ('dream_league_cup', 'Semi-Finals', 'SHEFSPANYOL', 'SPORTING HOOF', 'SHEFSPANYOL', 'SPORTING HOOF', 3, 0, null),
  ('dream_league_cup', 'Final', 'ERIMUS', 'SHEFSPANYOL', 'ERIMUS', 'SHEFSPANYOL', -1, 0, null)
) as v(competition, round_name, home_team, away_team, home_name, away_name, home_score, away_score, played_on)
 on s.name='2023/2024'
left join public.teams ht on ht.season_id=s.id and ht.name=v.home_team
left join public.teams at on at.season_id=s.id and at.name=v.away_team;
insert into public.honours (season_id, team_id, title, season_label)
select s.id, t.id, v.title, v.season_label from public.seasons s join (values
  ('SHEFSPANYOL', 'League Champions', '23/24'),
  ('SHEFSPANYOL', 'Cup Winners', '23/24')
) as v(team_name, title, season_label) on s.name='2023/2024'
join public.teams t on t.season_id=s.id and t.name=v.team_name;
